function parseTaskLogEvents(content = "") {
    return String(content || "")
        .split(/\r?\n/)
        .map((line, index) => ({ line, index }))
        .filter(({ line }) => line.trim())
        .flatMap(({ line, index }) => {
            try {
                const event = JSON.parse(line);
                if (!event || typeof event !== "object" || Array.isArray(event)) return [];
                return [{ ...event, _sourceIndex: index }];
            } catch {
                return [];
            }
        })
        .sort((left, right) => {
            const sequenceDifference = Number(left.sequence || 0) - Number(right.sequence || 0);
            if (sequenceDifference !== 0) return sequenceDifference;
            const timeDifference = String(left.timestamp || "").localeCompare(String(right.timestamp || ""));
            return timeDifference || left._sourceIndex - right._sourceIndex;
        })
        .map(({ _sourceIndex, ...event }) => event);
}

function parseArgs(input = "") {
    const args = [];
    let current = "";
    let quote = null;
    let escaped = false;

    for (const char of input) {
        if (escaped) {
            current += char;
            escaped = false;
            continue;
        }

        if (char === "\\") {
            escaped = true;
            continue;
        }

        if (quote) {
            if (char === quote) {
                quote = null;
            } else {
                current += char;
            }
            continue;
        }

        if (char === "'" || char === "\"") {
            quote = char;
            continue;
        }

        if (/\s/.test(char)) {
            if (current.length > 0) {
                args.push(current);
                current = "";
            }
            continue;
        }

        current += char;
    }

    if (escaped) current += "\\";
    if (quote) throw new Error("命令参数存在未闭合的引号");
    if (current.length > 0) args.push(current);
    return args;
}

function parseEnvText(text = "") {
    const env = {};
    for (const rawLine of String(text).split(/\r?\n/)) {
        const line = rawLine.trim();
        if (!line || line.startsWith("#")) continue;
        const index = line.indexOf("=");
        if (index <= 0) continue;
        const key = line.slice(0, index).trim();
        const value = line.slice(index + 1);
        if (/^[A-Za-z_][A-Za-z0-9_]*$/.test(key)) {
            env[key] = value;
        }
    }
    return env;
}

function maskEnvText(text = "") {
    return String(text)
        .split(/\r?\n/)
        .map((line) => {
            const trimmed = line.trim();
            if (!trimmed || trimmed.startsWith("#") || !trimmed.includes("=")) return line;
            return `${line.slice(0, line.indexOf("="))}=********`;
        })
        .join("\n");
}

function fillTemplate(template, context = {}) {
    let output = String(template || "");
    const replacements = {
        ...context,
        prompt: context.prompt || "",
        targetFile: context.targetFile || context.taskFile || "",
        taskFile: context.taskFile || context.targetFile || "",
        "目标任务文件": context.targetFile || context.taskFile || "",
        requirement: context.requirement || "",
        title: context.title || "",
        workingDirectory: context.workingDirectory || "",
    };

    for (const [key, value] of Object.entries(replacements)) {
        if (!key) continue;
        const escaped = key.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
        const renderedValue = Array.isArray(value)
            ? value.join("\n")
            : value === null || value === undefined
                ? ""
                : typeof value === "object"
                    ? JSON.stringify(value)
                    : String(value);
        output = output
            .replace(new RegExp(`\\$\\{\\s*${escaped}\\s*\\}`, "g"), () => renderedValue)
            .replace(new RegExp(`\\{\\{\\s*${escaped}\\s*\\}\\}`, "g"), () => renderedValue)
            .replace(new RegExp(`\\{\\s*${escaped}\\s*\\}`, "g"), () => renderedValue);
    }
    return output;
}

