+                        "Write-Output $env:CLAUDE_LOOP_TEST_OUTPUT",
+                        "exit ([int]$env:CLAUDE_LOOP_TEST_EXIT_CODE)",
+                        "",
+                    ].join("\n"), "utf8");
+                    args = [
