+                        "loop-test", path.join(__dirname, "..", "claude_loop.sh").replace(/\\/g, "/"),
+                    ];
+                }
+
+                const result = childProcess.spawnSync(shell.command, args, {
+                    cwd: tempRoot,
+                    encoding: "utf8",
+                    timeout: 10000,
+                    windowsHide: true,
