    }

    Write-LoopLog "Other result; waiting $RetryWaitSeconds seconds before retry."

    $currentHash = Get-TaskFileHash
    if ($output -eq $lastOutput -and $currentHash -eq $hashBefore) {
        $sameCount += 1
